package vn.covie.outbox.application; import org.springframework.beans.factory.annotation.Value; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Component; @Component public class OutboxScheduler {private final OutboxProcessor processor;private final int max;private final vn.covie.ops.ScheduledJobMetrics metrics;public OutboxScheduler(OutboxProcessor processor,@Value("${covie.outbox.max-events-per-poll:50}")int max,vn.covie.ops.ScheduledJobMetrics metrics){this.processor=processor;this.max=max;this.metrics=metrics;}@Scheduled(fixedDelayString="${covie.outbox.poll-delay-ms:500}")public void poll(){metrics.run(vn.covie.ops.ScheduledJobMetrics.Job.OUTBOX,()->{for(int i=0;i<max&&processor.processOne();i++);});}}
